tape( 'the function returns `true` if both arrays have equal values (mixed 64-bit integer arrays)', function test( t ) {
	var out;
	var x;
	var y;

	// Signed and unsigned 64-bit integer arrays:
	x = new Uint64Array( [ 0, 1, 2, 3 ] );
	y = new Int64Array( [ 0, 1, 2, 3 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	// Values exceeding the maximum safe integer (2^60 and 2^64-2^11):
	x = new Uint64Array([
		1,
		Uint64.of( 268435456, 0 ),
		Uint64.of( 4294967295, 4294965248 )
	]);
	y = new Float64Array([
		1.0,
		1152921504606846976.0,
		18446744073709549568.0
	]);
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	// Negative values and values exceeding the maximum safe integer (-2^63, -2^32, and 2^63-2^10):
	x = new Int64Array([
		Int64.of( 2147483648, 0 ),
		-4294967296,
		-1,
		0,
		1,
		Int64.of( 2147483647, 4294966272 )
	]);
	y = new Float64Array([
		-9223372036854775808.0,
		-4294967296.0,
		-1.0,
		0.0,
		1.0,
		9223372036854774784.0
	]);
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	// Lower precision integer arrays:
	x = new Uint64Array( [ 0, 1, 2, 4294967295 ] );
	y = new Uint32Array( [ 0, 1, 2, 4294967295 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Int64Array( [ -2147483648, -1, 0, 2147483647 ] );
	y = new Int32Array( [ -2147483648, -1, 0, 2147483647 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Uint64Array( [ 0, 1, 2, 255 ] );
	y = new Uint8Array( [ 0, 1, 2, 255 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Int64Array( [ -128, -1, 0, 127 ] );
	y = new Int8Array( [ -128, -1, 0, 127 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Uint64Array( [ 0, 1, 2, 3 ] );
	y = new Int32Array( [ 0, 1, 2, 3 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	// Unsigned 32-bit values exceeding the maximum 32-bit signed integer (2^31 and 2^32-1):
	x = new Int64Array( [ 0, 2147483648, 4294967295 ] );
	y = new Uint32Array( [ 0, 2147483648, 4294967295 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Int64Array( [ 0, 1, 2, 3 ] );
	y = new Uint8Array( [ 0, 1, 2, 3 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	// Floating-point arrays:
	x = new Uint64Array( [ 0, 1, 2, 3 ] );
	y = new Float32Array( [ 0.0, 1.0, 2.0, 3.0 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Int64Array( [ 0, -1, 2, -3 ] );
	y = new Float32Array( [ 0.0, -1.0, 2.0, -3.0 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	// Accessor arrays:
	x = new Uint64Array( [ 0, 1, 2, 3 ] );
	y = new AccessorArray( [ 0, 1, 2, 3 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	x = new Int64Array( [ 0, -1, 2, 3 ] );
	y = new AccessorArray( [ 0, -1, 2, 3 ] );
	out = hasEqualValues( x, y );
	t.strictEqual( out, true, 'returns expected value' );

	out = hasEqualValues( y, x );
	t.strictEqual( out, true, 'returns expected value' );

	t.end();
});

